"""Additive 2.0 ownership and immutable snapshot contracts.

Frozen SQLite DDL. Does not drop/rebuild tables or infer legacy ownership.
0001 dynamically creates current metadata on fresh DBs, so operations check
existing objects and also work on a real 0001 legacy database.
Downgrade is refused: restoring a verified backup is the safe recovery path.
"""
from alembic import op
import sqlalchemy as sa

revision = "0002_geulbit_v2"
