INDEX_DDL = [('ix_consents_user_id', 'CREATE INDEX ix_consents_user_id ON consents (user_id)'), ('ix_works_owner_id', 'CREATE INDEX ix_works_owner_id ON works (owner_id)'), ('ix_document_revisions_document_id', 'CREATE INDEX ix_document_revisions_document_id ON document_revisions (document_id)'), ('ix_feedback_reactions_analysis_id', 'CREATE INDEX ix_feedback_reactions_analysis_id ON feedback_reactions (analysis_id)'), ('ix_ai_interactions_user_id', 'CREATE INDEX ix_ai_interactions_user_id ON ai_interactions (user_id)'), ('ix_writing_owner_id', 'CREATE INDEX ix_writing_owner_id ON writing (owner_id)'), ('ix_analysis_essay_version_id', 'CREATE INDEX ix_analysis_essay_version_id ON analysis (essay_version_id)'), ('ix_source_document_owner_id', 'CREATE INDEX ix_source_document_owner_id ON source_document (owner_id)')]

TRIGGERS = {'v2_version_no_update': "BEFORE UPDATE ON writing_version WHEN OLD.snapshot_hash IS NOT NULL BEGIN SELECT RAISE(ABORT,'IMMUTABLE_VERSION'); END", 'v2_document_revision_no_update': "BEFORE UPDATE ON document_revisions BEGIN SELECT RAISE(ABORT,'APPEND_ONLY_REVISION'); END", 'v2_analysis_input_no_update': "BEFORE UPDATE OF essay_version_id,input_manifest,context_snapshot,schema_version,engine_version,ruleset_hash ON analysis WHEN OLD.essay_version_id IS NOT NULL BEGIN SELECT RAISE(ABORT,'IMMUTABLE_ANALYSIS_INPUT'); END", 'v2_analysis_result_no_update': "BEFORE UPDATE ON analysis WHEN OLD.result_snapshot IS NOT NULL BEGIN SELECT RAISE(ABORT,'IMMUTABLE_ANALYSIS_RESULT'); END", 'v2_analysis_version_insert': "BEFORE INSERT ON analysis WHEN NEW.essay_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM writing_version v WHERE v.id=NEW.essay_version_id AND v.writing_id=NEW.writing_id AND v.snapshot_hash IS NOT NULL) BEGIN SELECT RAISE(ABORT,'UNTRUSTED_OR_FOREIGN_VERSION'); END", 'v2_current_version_insert': "BEFORE INSERT ON writing WHEN NEW.current_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM writing_version v WHERE v.id=NEW.current_version_id AND v.writing_id=NEW.id AND v.snapshot_hash IS NOT NULL) BEGIN SELECT RAISE(ABORT,'FOREIGN_CURRENT_VERSION'); END", 'v2_revision_parent_insert': "BEFORE INSERT ON document_revisions WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM document_revisions p WHERE p.id=NEW.parent_id AND p.document_id=NEW.document_id AND p.revision_number<NEW.revision_number) BEGIN SELECT RAISE(ABORT,'FOREIGN_REVISION_PARENT'); END", 'v2_version_parent_insert': "BEFORE INSERT ON writing_version WHEN NEW.snapshot_hash IS NOT NULL AND (length(NEW.snapshot_hash)!=64 OR NEW.normalization_version!='nfc-lf/1' OR (NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM writing_version p WHERE p.id=NEW.parent_id AND p.writing_id=NEW.writing_id AND p.version_number<NEW.version_number))) BEGIN SELECT RAISE(ABORT,'INVALID_CERTIFIED_VERSION'); END", 'v2_document_access_insert': "BEFORE INSERT ON source_document WHEN NEW.scope IS NOT NULL AND (NEW.scope NOT IN ('PUBLIC','PRIVATE') OR NEW.document_type NOT IN ('TEXT','CRITERIA','REFERENCE','INFO') OR NEW.access_mode NOT IN ('MATCH_ONLY','VIEW','DOWNLOAD') OR NEW.owner_id IS NULL OR (NEW.scope='PUBLIC' AND COALESCE(NEW.rights_confirmed,0)!=1)) BEGIN SELECT RAISE(ABORT,'INVALID_DOCUMENT_ACCESS'); END", 'v2_analysis_version_update': "BEFORE UPDATE ON analysis WHEN NEW.essay_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM writing_version v WHERE v.id=NEW.essay_version_id AND v.writing_id=NEW.writing_id AND v.snapshot_hash IS NOT NULL) BEGIN SELECT RAISE(ABORT,'UNTRUSTED_OR_FOREIGN_VERSION'); END", 'v2_current_version_update': "BEFORE UPDATE ON writing WHEN NEW.current_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM writing_version v WHERE v.id=NEW.current_version_id AND v.writing_id=NEW.id AND v.snapshot_hash IS NOT NULL) BEGIN SELECT RAISE(ABORT,'FOREIGN_CURRENT_VERSION'); END", 'v2_revision_parent_update': "BEFORE UPDATE ON document_revisions WHEN NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM document_revisions p WHERE p.id=NEW.parent_id AND p.document_id=NEW.document_id AND p.revision_number<NEW.revision_number) BEGIN SELECT RAISE(ABORT,'FOREIGN_REVISION_PARENT'); END", 'v2_version_parent_update': "BEFORE UPDATE ON writing_version WHEN NEW.snapshot_hash IS NOT NULL AND (length(NEW.snapshot_hash)!=64 OR NEW.normalization_version!='nfc-lf/1' OR (NEW.parent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM writing_version p WHERE p.id=NEW.parent_id AND p.writing_id=NEW.writing_id AND p.version_number<NEW.version_number))) BEGIN SELECT RAISE(ABORT,'INVALID_CERTIFIED_VERSION'); END", 'v2_document_access_update': "BEFORE UPDATE ON source_document WHEN NEW.scope IS NOT NULL AND (NEW.scope NOT IN ('PUBLIC','PRIVATE') OR NEW.document_type NOT IN ('TEXT','CRITERIA','REFERENCE','INFO') OR NEW.access_mode NOT IN ('MATCH_ONLY','VIEW','DOWNLOAD') OR NEW.owner_id IS NULL OR (NEW.scope='PUBLIC' AND COALESCE(NEW.rights_confirmed,0)!=1)) BEGIN SELECT RAISE(ABORT,'INVALID_DOCUMENT_ACCESS'); END", 'v2_writing_owner_no_transfer': "BEFORE UPDATE OF owner_id ON writing WHEN OLD.owner_id IS NOT NULL AND NEW.owner_id IS NOT OLD.owner_id BEGIN SELECT RAISE(ABORT,'OWNER_TRANSFER_FORBIDDEN'); END", 'v2_source_document_owner_no_transfer': "BEFORE UPDATE OF owner_id ON source_document WHEN OLD.owner_id IS NOT NULL AND NEW.owner_id IS NOT OLD.owner_id BEGIN SELECT RAISE(ABORT,'OWNER_TRANSFER_FORBIDDEN'); END"}

def upgrade():
    bind = op.get_bind()
    if bind.dialect.name != "sqlite":
        raise RuntimeError("SQLITE_REQUIRED")
    # sqlite3 legacy transaction mode does not BEGIN for DDL. Explicit BEGIN
    # ensures CREATE/ALTER and Alembic revision update roll back together.
    if not bind.connection.driver_connection.in_transaction:
        bind.exec_driver_sql("BEGIN IMMEDIATE")
    names = set(sa.inspect(bind).get_table_names())
    for name, ddl in TABLE_DDL.items():
        if name not in names:
            op.execute(ddl)
    for table, columns in ADDITIONS.items():
        existing = {c["name"] for c in sa.inspect(bind).get_columns(table)}
        for name, ddl in columns.items():
            if name not in existing:
                op.execute("ALTER TABLE " + table + " ADD COLUMN " + ddl)
    for name, ddl in INDEX_DDL:
        exists = bind.exec_driver_sql("SELECT 1 FROM sqlite_master WHERE type='index' AND name=?", (name,)).first()
        if not exists:
            op.execute(ddl)
    op.execute("CREATE UNIQUE INDEX IF NOT EXISTS uq_certified_version_number ON writing_version(writing_id,version_number) WHERE snapshot_hash IS NOT NULL")
    for name, ddl in TRIGGERS.items():
        op.execute("CREATE TRIGGER IF NOT EXISTS " + name + " " + ddl)


def downgrade():
    raise RuntimeError("NONDESTRUCTIVE_DOWNGRADE_UNAVAILABLE_RESTORE_VERIFIED_BACKUP")
